"  const bypassedPermissionsRef = useRef(new Set());

  const [passcodeModal, setPasscodeModal] = useState({
    isOpen: false,
    actionKey: '',
    actionName: '',
    onSuccess: null
  });

  const executeWithBypass = async (perm, callback) => {
    bypassedPermissionsRef.current.add(perm);
    try {
      await callback();
    } finally {
      bypassedPermissionsRef.current.delete(perm);
    }
  };

  const getPermissionValue = (section, perm) => {
    const access = getStaffPermissions()?.pos_access;
    if (!access) return true;
    const parts = section.split('.');
    let current = access;
    for (const part of parts) {
      if (current) {
        current = current[part];
      }
    }
    if (!current) return true;
    return current[perm];
  };

  const isFeatureVisible = (section, perm) => {
    const directVal = getPermissionValue(section, perm);
    const passcodeVal = getPermissionValue(section, `${perm}_passcode`);
    return directVal !== false || passcodeVal === true;
  };

  const checkPermissionAndExecute = (section, perm, actionName, onExecute) => {
    const directVal = getPermissionValue(section, perm);
    const passcodeVal = getPermissionValue(section, `${perm}_passcode`);

    if (directVal !== false && passcodeVal !== true) {
      onExecute();
    } else {
      setPasscodeModal({
        isOpen: true,
        actionKey: perm,
        actionName: actionName,
        onSuccess: () => executeWithBypass(perm, onExecute)
      });
    }
  };"

